sum_layernorm_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void sum_layernorm_kernel(
    const float* input, float* output, float sum_weight,
    const float* gamma, const float* beta,
    int batch_size, int C, int D, int H, int W, float eps
) {
    int spatial_idx = blockIdx.x;
    int batch = spatial_idx / (D * H * W);
    int spatial_offset = spatial_idx % (D * H * W);
    int d = spatial_offset / (H * W);
    int h = (spatial_offset % (H * W)) / W;
    int w = spatial_offset % W;

    if (batch >= batch_size) return;

    extern __shared__ float shared[];
    float* sum_shared = shared;
    float* sum_sq_shared = &shared[blockDim.x];

    int c = threadIdx.x;
    int input_idx = ((batch * C + c) * D + d) * H * W + h * W + w;
    float val = input[input_idx] + sum_weight;

    // Initialize shared memory
    sum_shared[c] = val;
    sum_sq_shared[c] = val * val;
    __syncthreads();

    // Parallel reduction for sum and sum_sq
    for (int s = blockDim.x/2; s>0; s>>=1) {
        if (c < s) {
            sum_shared[c] += sum_shared[c + s];
            sum_sq_shared[c] += sum_sq_shared[c + s];
        }
        __syncthreads();
    }

    if (c == 0) {
        float mean = sum_shared[0] / C;
        float var = sum_sq_shared[0]/C - mean*mean + eps;
        float inv_std = rsqrtf(var);
        shared[2*blockDim.x] = mean;
        shared[2*blockDim.x + 1] = inv_std;
    }
    __syncthreads();

    float mean = shared[2*blockDim.x];
    float inv_std = shared[2*blockDim.x + 1];
    output[input_idx] = (val - mean) * inv_std * gamma[c] + beta[c];
}

torch::Tensor sum_layernorm_cuda(
    torch::Tensor input, torch::Tensor sum_weight,
    torch::Tensor gamma, torch::Tensor beta, float eps
) {
    auto output = torch::empty_like(input);
    int batch_size = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);

    int total_spatial = batch_size * D * H * W;
    dim3 grid(total_spatial);
    dim3 block(C);
    size_t shared_size = 2*C*sizeof(float) + 2*sizeof(float);

    sum_layernorm_kernel<<<grid, block, shared_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        sum_weight.item<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        batch_size, C, D, H, W, eps
    );

    return output;
}
"""

avgpool_gelu_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void avgpool_gelu_kernel(
    const float* input, float* output,
    int batch_size, int C, int D, int H, int W
) {
    int d_out = blockIdx.x;
    int h_out = blockIdx.y;
    int w_out = blockIdx.z;
    int batch = threadIdx.y;
    int c = threadIdx.x;

    if (batch >= batch_size || c >= C) return;

    int D_out = D / 2;
    int H_out = H / 2;
    int W_out = W / 2;

    float sum = 0.0f;
    for(int dd=0; dd<2; ++dd) {
        for(int hh=0; hh<2; ++hh) {
            for(int ww=0; ww<2; ++ww) {
                int d_in = d_out*2 + dd;
                int h_in = h_out*2 + hh;
                int w_in = w_out*2 + ww;
                if (d_in < D && h_in < H && w_in < W) {
                    int idx = ((batch*C + c)*D + d_in)*H*W + h_in*W + w_in;
                    sum += input[idx];
                }
            }
        }
    }

    float avg = sum / 8.0f;
    // GELU approximation
    avg = 0.5f * avg * (1.0f + tanhf(0.7978845608f * (avg + 0.044715f * avg * avg * avg)));

    int out_idx = ((batch*C + c)*D_out + d_out)*H_out*W_out + h_out*W_out + w_out;
    output[out_idx] = avg;
}

torch::Tensor avgpool_gelu_cuda(torch::Tensor input) {
    int batch_size = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);

    auto output = torch::empty({batch_size, C, D/2, H/2, W/2}, input.options());

    dim3 grid(D/2, H/2, W/2);
    dim3 block(C, batch_size);

    avgpool_gelu_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size, C, D, H, W
    );

    return output;
}
"""

# Compile custom kernels
sum_layernorm = load_inline(
    name='sum_layernorm',
    cpp_sources='torch::Tensor sum_layernorm_cuda(torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor, float);',
    cuda_sources=sum_layernorm_source,
    functions=['sum_layernorm_cuda'],
    verbose=True
)

avgpool_gelu = load_inline(
    name='avgpool_gelu',
    cpp_sources='torch::Tensor avgpool_gelu_cuda(torch::Tensor);',
    cuda_sources=avgpool_gelu_source,
