)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, sum_weight, norm_shape, pool_kernel_size):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding,
            output_padding=output_padding
        )
        self.sum_weight = nn.Parameter(torch.tensor(sum_weight))
        self.gamma = nn.Parameter(torch.ones(*norm_shape))
        self.beta = nn.Parameter(torch.zeros(*norm_shape))
        self.eps = 1e-5

    def forward(self, x):
        x = self.conv_transpose(x)
        x = sum_layernorm.sum_layernorm_cuda(
            x, self.sum_weight, self.gamma, self.beta, self.eps
        )
        x = avgpool_gelu.avgpool_gelu_cuda(x)
        return x
